begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
\ir ../fixtures/agenda.psql

select has_function('public','bc_support_service',array['uuid','uuid','text','jsonb'],'Serviço operacional existe');
insert into fixture values('support-session','a1000000-0000-4000-8000-000000000090');
insert into auth.sessions(id,user_id,created_at,updated_at) values(pg_temp.f('support-session'),pg_temp.f('ordinary'),now(),now());
insert into fixture values('worker-session','a1000000-0000-4000-8000-000000000092'),('other-client','a1000000-0000-4000-8000-000000000093');
insert into auth.sessions(id,user_id,created_at,updated_at) values(pg_temp.f('worker-session'),pg_temp.f('worker'),now(),now());
insert into public.clientes(id,nome,telefone,created_by) values(pg_temp.f('other-client'),'Outra pessoa fictícia CI','31000000000',pg_temp.f('admin'));
update public.staff_profiles set profissao='Profissional CI',conselho='Conselho fictício',registro_conselho='CI' where user_id=pg_temp.f('worker');
select set_config('request.jwt.claim.sub',pg_temp.f('worker')::text,true);
set local role authenticated;
insert into fixture values('support-treatment',public.bc_treatment_create(pg_temp.f('client'),pg_temp.f('procedure')));
insert into fixture select 'support-document',(public.bc_treatment_prepare_consent(pg_temp.f('support-treatment'))->>'document_id')::uuid;
reset role;
insert into public.clinical_signatures(document_id,signer_kind,signer_user_id,signer_name,storage_path,sha256,recorded_by)
values(pg_temp.f('support-document'),'paciente',null,'Cliente fictícia CI','assinaturas/ci/paciente.png',repeat('0',64),pg_temp.f('worker')),
 (pg_temp.f('support-document'),'profissional',pg_temp.f('worker'),'Profissional fictícia CI','assinaturas/ci/profissional.png',repeat('0',64),pg_temp.f('worker'));
update public.clinical_documents set status='emitido',storage_path='documentos/consentimentos/ci/original.pdf',sha256=repeat('0',64),generated_at=now() where id=pg_temp.f('support-document');
insert into storage.objects(bucket_id,name,metadata) values('bc-prontuario-private','arquivos-clientes/a1000000-0000-4000-8000-000000000005/a1000000-0000-4000-8000-000000000094.pdf','{"mimetype":"application/pdf","size":20}'),
 ('bc-prontuario-private','arquivos-clientes/a1000000-0000-4000-8000-000000000005/a1000000-0000-4000-8000-000000000095.pdf','{}');
update public.staff_profiles set role='admin_criacao',atende_clientes=false,pode_gerenciar_agendas=false,pode_gerenciar_procedimentos=false,procedure_scope='explicit' where user_id=pg_temp.f('ordinary');
select ok(not has_function_privilege('authenticated','public.bc_support_service(uuid,uuid,text,jsonb)','execute'),'JWT de usuário não executa serviço privilegiado direto');
select ok(not has_function_privilege('anon','public.bc_support_service(uuid,uuid,text,jsonb)','execute'),'Anônimo não executa serviço');
set local role service_role;
select lives_ok(format('select public.bc_support_service(%L,%L,''client_get'',%L)',pg_temp.f('ordinary'),pg_temp.f('support-session'),jsonb_build_object('clientId',pg_temp.f('client'),'reason','Apoio CI')::text),'Operador ativo consulta projeção');
select is(jsonb_array_length(public.bc_support_service(pg_temp.f('ordinary'),pg_temp.f('support-session'),'client_get',jsonb_build_object('clientId',pg_temp.f('client'),'reason','Apoio CI'))->'documents'),1,'Somente PDF primário assinado aparece');
select throws_ok(format('select public.bc_support_service(%L,%L,''client_get'',%L)',pg_temp.f('worker'),pg_temp.f('worker-session'),jsonb_build_object('clientId',pg_temp.f('client'),'reason','Apoio CI')::text),'42501','Acesso operacional não autorizado.','Colaboradora com sessão própria não herda apoio administrativo');
select throws_ok(format('select public.bc_support_service(%L,%L,''upload_check'',%L)',pg_temp.f('ordinary'),pg_temp.f('support-session'),jsonb_build_object('clientId',pg_temp.f('other-client'),'documentId',pg_temp.f('support-document'),'reason','Apoio CI')::text),'42501','Consentimento original indisponível.','Documento de outra cliente não recebe cópia');
select throws_ok(format('select public.bc_support_service(%L,%L,''register_returned'',%L)',pg_temp.f('ordinary'),pg_temp.f('support-session'),jsonb_build_object('clientId',pg_temp.f('client'),'documentId',pg_temp.f('support-document'),'storagePath','arquivos-clientes/a1000000-0000-4000-8000-000000000005/a1000000-0000-4000-8000-000000000095.pdf','sizeBytes',20,'sha256',repeat('1',64),'reason','Apoio CI')::text),'22023','Arquivo enviado não confere.','Metadata ausente não passa por lógica NULL');
select lives_ok(format('select public.bc_support_service(%L,%L,''register_returned'',%L)',pg_temp.f('ordinary'),pg_temp.f('support-session'),jsonb_build_object('clientId',pg_temp.f('client'),'documentId',pg_temp.f('support-document'),'storagePath','arquivos-clientes/a1000000-0000-4000-8000-000000000005/a1000000-0000-4000-8000-000000000094.pdf','sizeBytes',20,'sha256',repeat('1',64),'reason','Apoio CI')::text),'Cópia devolvida é anexada sem reescrever original');
select throws_ok(format('select public.bc_support_service(%L,%L,''client_get'',%L)',pg_temp.f('worker'),pg_temp.f('support-session'),jsonb_build_object('clientId',pg_temp.f('client'),'reason','Apoio CI')::text),'42501','Acesso operacional não autorizado.','Sessão de outra identidade não serve');
select throws_ok(format('select public.bc_support_service(%L,%L,''client_update'',%L)',pg_temp.f('ordinary'),pg_temp.f('support-session'),jsonb_build_object('clientId',pg_temp.f('client'),'expectedUpdatedAt',now(),'patch',jsonb_build_object('final_price',700),'reason','Apoio CI')::text),'22023','Campo cadastral não permitido.','Mesmo serviço rejeita campo financeiro');
reset role;
create temporary table support_saved as select updated_at from public.clientes where id=pg_temp.f('client');
grant select on support_saved to service_role;
set local role service_role;
select lives_ok(format('select public.bc_support_service(%L,%L,''client_update'',%L)',pg_temp.f('ordinary'),pg_temp.f('support-session'),jsonb_build_object('clientId',pg_temp.f('client'),'expectedUpdatedAt',(select updated_at from support_saved),'patch',jsonb_build_object('nome','Pessoa fictícia corrigida'),'reason','Correção CI')::text),'Correção cadastral autorizada');
select throws_ok(format('select public.bc_support_service(%L,%L,''client_update'',%L)',pg_temp.f('ordinary'),pg_temp.f('support-session'),jsonb_build_object('clientId',pg_temp.f('client'),'expectedUpdatedAt','2000-01-01T00:00:00Z','patch',jsonb_build_object('nome','Não sobrescrever'),'reason','Correção CI')::text),'40001','Cadastro atualizado por outra pessoa. Reabra a ficha.','Versão antiga não sobrescreve edição');
select throws_ok(format('select public.bc_support_service(%L,%L,''download'',%L)',pg_temp.f('ordinary'),pg_temp.f('support-session'),jsonb_build_object('clientId',pg_temp.f('client'),'documentId',pg_temp.f('version'),'kind','original','reason','Apoio CI')::text),'42501','Documento indisponível para apoio.','ID de outra entidade não abre documentos');
select throws_ok(format('select public.bc_support_service(%L,%L,''invite_reserve'',%L)',pg_temp.f('ordinary'),pg_temp.f('support-session'),'{"name":"Não alterar conta","email":"admin-agenda@example.invalid"}'),'23505','Já existe uma conta para este e-mail.','Convite não assume conta existente');
reset role;
create temporary table support_invite as select public.bc_support_service(pg_temp.f('ordinary'),pg_temp.f('support-session'),'invite_reserve','{"name":"Nova colaboradora fictícia","email":"nova-support@example.invalid"}') as data;
grant select on support_invite to service_role;
insert into fixture values('new-staff','a1000000-0000-4000-8000-000000000096');
insert into auth.users(instance_id,id,aud,role,email,created_at,updated_at) values('00000000-0000-0000-0000-000000000000',pg_temp.f('new-staff'),'authenticated','authenticated','nova-support@example.invalid',now(),now());
set local role service_role;
select lives_ok(format('select public.bc_support_service(%L,%L,''invite_finish'',%L)',pg_temp.f('ordinary'),pg_temp.f('support-session'),jsonb_build_object('invitationId',(select data->>'invitationId' from support_invite),'userId',pg_temp.f('new-staff'))::text),'Convite termina em colaboradora sem capacidades clínicas');
reset role;
select is((select role from public.staff_profiles where user_id=pg_temp.f('new-staff')),'colaborador','Papel fixo colaborador');
select is((select atende_clientes or pode_gerenciar_agendas or pode_gerenciar_procedimentos from public.staff_profiles where user_id=pg_temp.f('new-staff')),false,'Convite não concede atendimento ou gerência');
select is((select procedure_scope from public.staff_profiles where user_id=pg_temp.f('new-staff')),'explicit','Sem execução clínica global');
insert into fixture values('admin-session','a1000000-0000-4000-8000-000000000097');
insert into auth.sessions(id,user_id,created_at,updated_at) values(pg_temp.f('admin-session'),pg_temp.f('admin'),now(),now());
set local role service_role;
select throws_ok(format('select public.bc_support_service(%L,%L,''activate_staff'',%L)',pg_temp.f('ordinary'),pg_temp.f('support-session'),jsonb_build_object('userId',pg_temp.f('new-staff'))::text),'42501','Acesso operacional não autorizado.','Criação não habilita capacidades clínicas');
select throws_ok(format('select public.bc_support_service(%L,%L,''activate_staff'',%L)',pg_temp.f('admin'),pg_temp.f('admin-session'),jsonb_build_object('userId',pg_temp.f('new-staff'))::text),'22023','Complete a identificação profissional antes de habilitar atendimento.','Admin precisa completar a identificação real');
reset role;
update public.staff_profiles set profissao='Profissional CI',conselho='Conselho CI',registro_conselho='CI' where user_id=pg_temp.f('new-staff');
set local role service_role;
select lives_ok(format('select public.bc_support_service(%L,%L,''activate_staff'',%L)',pg_temp.f('admin'),pg_temp.f('admin-session'),jsonb_build_object('userId',pg_temp.f('new-staff'))::text),'Admin conclui novo cadastro');
reset role;
select is((select atende_clientes from public.staff_profiles where user_id=pg_temp.f('new-staff')),true,'Colaboradora aparece para configurar procedimentos');
select is((select procedure_scope from public.staff_profiles where user_id=pg_temp.f('new-staff')),'explicit','Ativação não concede procedimentos globalmente');
select is((select sha256 from public.clinical_documents where id=pg_temp.f('support-document')),repeat('0',64),'Hash original permanece intacto');
select is((select count(*)::integer from private.bc_support_consent_copies),1,'Uma cópia vinculada');
select is((select nome from public.clientes where id=pg_temp.f('client')),'Pessoa fictícia corrigida','Cadastro atualizado e somente cadastro');
select ok(exists(select 1 from public.audit_log where actor_user_id=pg_temp.f('ordinary') and action='support_client_updated'),'Autoria da correção registrada');
select is(private.is_bc_creation_identity(),false,'Contexto service não assume papel clínico de usuário');
update public.staff_profiles set active=false where user_id=pg_temp.f('ordinary');
set local role service_role;
select throws_ok(format('select public.bc_support_service(%L,%L,''client_get'',%L)',pg_temp.f('ordinary'),pg_temp.f('support-session'),jsonb_build_object('clientId',pg_temp.f('client'),'reason','Apoio CI')::text),'42501','Acesso operacional não autorizado.','Desativação revoga cada operação');
reset role;
update public.staff_profiles set active=true where user_id=pg_temp.f('ordinary');
delete from auth.sessions where id=pg_temp.f('support-session');
set local role service_role;
select throws_ok(format('select public.bc_support_service(%L,%L,''client_get'',%L)',pg_temp.f('ordinary'),pg_temp.f('support-session'),jsonb_build_object('clientId',pg_temp.f('client'),'reason','Apoio CI')::text),'42501','Acesso operacional não autorizado.','Sessão revogada não é reutilizável');
reset role;
select * from finish();
rollback;
